  "inlineSchema": "//* ============= AUDIT LOG DOMAIN =============\n//* GENERIC CHANGE-HISTORY TABLE — REPLACES THE NEED FOR EVERY NEW MUTABLE\n//* MODEL TO GROW ITS OWN createdBy/updatedBy/deletedBy RELATION TRIO BACK TO\n//* User. SEE docs/audit-log.md FOR THE POPULATION MECHANISM (A PRISMA CLIENT\n//* EXTENSION, src/prisma/extensions/audit-log.extension.ts) AND THE TRACKED-\n//* MODEL ALLOWLIST. entityType IS A PLAIN STRING (THE PRISMA MODEL NAME), NOT\n//* AN ENUM HERE — TRACKING A NEW MODEL IS A CODE-ONLY CHANGE, NEVER A\n//* MIGRATION, WHICH IS THE WHOLE POINT OF \"GENERIC\".\n\nenum AuditAction {\n  CREATE\n  UPDATE\n  SOFT_DELETE\n  DELETE\n}\n\nmodel AuditLog {\n  id Int @id @default(autoincrement())\n\n  actorId Int?  @map(\"actor_id\")\n  actor   User? @relation(\"AuditLogActor\", fields: [actorId], references: [id], onDelete: SetNull)\n\n  entityType String      @map(\"entity_type\")\n  entityId   Int         @map(\"entity_id\")\n  action     AuditAction\n  diff       Json?\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(3)\n\n  @@index([entityType, entityId])\n  @@index([actorId])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\nenum BlogStatus {\n  PUBLISHED\n  DRAFT\n  ARCHIVED\n}\n\n// =========== BLOG MODEL ============\nmodel Blog {\n  id     Int        @id @default(autoincrement())\n  sid    String     @unique @default(uuid()) @db.Uuid\n  status BlogStatus @default(DRAFT)\n\n  title        String  @db.VarChar(255)\n  slug         String  @unique @db.VarChar(255)\n  content      String  @db.Text\n  blogCategory String? @db.VarChar(100) // E.g. \"Guides\", \"Announcements\"\n\n  imageUrl String? @db.VarChar(512)\n\n  totalComments Int @default(0) // Simple counter for now\n\n  // SEO Metadata\n  metaTitle       String? @db.VarChar(255)\n  metaDescription String? @db.Text\n\n  // Timestamps\n  createdAt   DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(3)\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(3)\n  publishedAt DateTime? @map(\"published_at\") @db.Timestamptz(3)\n\n  // Relations\n  authorId Int?  @map(\"author_id\")\n  author   User? @relation(fields: [authorId], references: [id], onDelete: SetNull)\n\n  @@index([status, publishedAt])\n  @@map(\"blogs\")\n}\n\n//* ROOT CONFIG FILE — GENERATOR + DATASOURCE ONLY\n//* NO MODELS OR ENUMS BELONG HERE — EACH DOMAIN OWNS ITS OWN .prisma FILE\n//* (user.prisma, blog.prisma, audit-log.prisma, ...)\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../../src/generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n//* ============= USER DOMAIN =============\n//* COVERS: AUTHENTICATION, PROFILE, SECURITY, OTP\n\nenum UserRole {\n  SUPER_ADMIN\n  ADMIN\n  MANAGER\n  USER\n}\n\nenum AuthProvider {\n  EMAIL\n  GOOGLE\n  FACEBOOK\n  APPLE\n}\n\nenum UserStatus {\n  PENDING_VERIFICATION\n  ACTIVE\n  INACTIVE\n  SUSPENDED\n  BLOCKED\n  DEACTIVATED\n  ARCHIVED\n}\n\nenum OTPType {\n  SIGNUP\n  PASSWORD_RESET\n  LOGIN_2FA\n  PHONE_CHANGE\n}\n\nmodel User {\n  id       Int     @id @default(autoincrement())\n  sid      String  @unique @default(uuid()) @map(\"user_sid\") @db.Uuid // Use native UUID type for performance\n  //* UNIQUE ONLY AMONG NON-DELETED ROWS — ENFORCED BY THE PARTIAL INDEX\n  //* \"users_email_active_key\" IN THE INIT MIGRATION. PRISMA'S DSL CAN'T\n  //* EXPRESS A FILTERED UNIQUE INDEX, SO THERE IS DELIBERATELY NO @unique HERE.\n  email    String\n  password String? // Null for OAuth\n  phone    String? @db.VarChar(20)\n\n  // Enums\n  role         UserRole     @default(USER)\n  status       UserStatus   @default(PENDING_VERIFICATION)\n  authProvider AuthProvider @default(EMAIL)\n  providerId   String? // OAuth ID\n\n  // Timestamps\n  createdAt   DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(3)\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(3)\n  lastLoginAt DateTime? @map(\"last_login_at\") @db.Timestamptz(3)\n  deletedAt   DateTime? @map(\"deleted_at\") @db.Timestamptz(3) //* FOR SOFT DELETE\n\n  // Relations\n  profile   Profile?\n  security  UserSecurity?\n  otps      OTP[]\n  blogs     Blog[]\n  auditLogs AuditLog[]    @relation(\"AuditLogActor\")\n\n  //* PREVENTS TWO ROWS FROM CLAIMING THE SAME OAUTH IDENTITY. NULLs (EVERY\n  //* EMAIL-AUTH USER) ARE NOT DISTINCT-CHECKED BY POSTGRES, SO THIS ONLY\n  //* CONSTRAINS ROWS THAT ACTUALLY HAVE A providerId.\n  @@unique([authProvider, providerId], map: \"users_auth_provider_provider_id_key\")\n  @@map(\"users\")\n}\n\nmodel Profile {\n  id          Int       @id @default(autoincrement())\n  firstName   String    @db.VarChar(100)\n  lastName    String?   @db.VarChar(100)\n  //* NO `name` COLUMN — A DISPLAY NAME IS ALWAYS DERIVED FROM\n  //* firstName/lastName AT READ TIME (src/common/utils/display-name.util.ts),\n  //* NEVER STORED, SO THERE IS NOTHING TO KEEP IN SYNC.\n  avatarUrl   String? // One source of truth for the image\n  bio         String?   @db.Text\n  dateOfBirth DateTime?\n  gender      String?   @db.VarChar(20)\n  metadata    Json?     @default(\"{}\")\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId      Int       @unique @map(\"user_id\")\n\n  //* pg_trgm GIN INDEXES — THE ADMIN USER-SEARCH ENDPOINT\n  //* (UserRepository.findAllUsers) RUNS A `contains`/ILIKE SUBSTRING SEARCH,\n  //* WHICH A BTREE CANNOT SERVE. THE pg_trgm EXTENSION IS ENABLED IN THE\n  //* INIT MIGRATION.\n  @@index([firstName(ops: raw(\"gin_trgm_ops\"))], type: Gin, map: \"profiles_first_name_trgm_idx\")\n  @@index([lastName(ops: raw(\"gin_trgm_ops\"))], type: Gin, map: \"profiles_last_name_trgm_idx\")\n  @@map(\"profiles\")\n}\n\nmodel UserSecurity {\n  id              Int       @id @default(autoincrement())\n  isEmailVerified Boolean   @default(false)\n  emailVerifiedAt DateTime? @db.Timestamptz(3)\n\n  //* SIGNUP/PASSWORD_RESET/LOGIN_2FA/PHONE_CHANGE VERIFICATION ALL FLOW\n  //* THROUGH THE `OTP` MODEL — NO PARALLEL TOKEN MECHANISM HERE.\n\n  // Security Logs\n  loginAttempts Int     @default(0)\n  //* NATIVE inet (NOT String) — VALIDATES ON WRITE AND KEEPS CIDR/RANGE\n  //* QUERIES AVAILABLE FOR FUTURE FRAUD/GEO RULES WITHOUT APP-LAYER PARSING.\n  lastLoginIp   String? @db.Inet\n  //* IP ALLOWLIST VALUE FOR INTERNAL RESTRICTED ACCESS. ADMIN-SET ONLY:\n  //* WRITTEN EXCLUSIVELY BY PATCH /user/update-user-security/:id (ADMIN GUARD).\n  //* CreateUserDto DELIBERATELY CARRIES NO `security` SUB-OBJECT, SO A PUBLIC\n  //* SELF-REGISTRATION CANNOT SEED THIS FIELD — A CALLER-CHOSEN VALUE WOULD\n  //* DEFEAT ANY IP RESTRICTION LATER BUILT ON TOP OF IT.\n  assignedIp    String? @db.Inet\n\n  user   User @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId Int  @unique @map(\"user_id\")\n\n  @@map(\"user_security\")\n}\n\nmodel OTP {\n  id        Int      @id @default(autoincrement())\n  code      String // Hashed code for security\n  type      OTPType\n  expiresAt DateTime @map(\"expires_at\") @db.Timestamptz(3)\n  isUsed    Boolean  @default(false) @map(\"is_used\")\n\n  // To identify the target\n  identifier String // * email or phone number\n\n  userId Int?  @map(\"user_id\") // Optional for identifiers not yet tied to an account\n  user   User? @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(3)\n\n  @@index([identifier])\n  @@map(\"otps\")\n}\n",
